import type { Metadata, Viewport } from "next";
import { Bricolage_Grotesque, Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import { Suspense } from "react";
import { AppShell, type ShellData } from "@/components/app-shell";
import { SyncOnOpen } from "@/components/sync-on-open";
import { ServiceWorker } from "@/components/service-worker";
import { PendingCallRecords } from "@/components/pending-call-records";
import { cookies } from "next/headers";
import { ThemePreference } from "@/components/theme-preference";
import { hasSupabase } from "@/lib/env";
import { requireWorkspace } from "@/lib/auth";

const sans = Geist({ subsets: ["latin"], variable: "--font-geist" });
const mono = Geist_Mono({ subsets: ["latin"], variable: "--font-geist-mono" });
const display = Bricolage_Grotesque({ subsets: ["latin"], variable: "--font-bricolage", axes: ["opsz"] });

export const metadata: Metadata = {
  title: { default: "Moneo — Personal Finance Workspace", template: "%s — Moneo" },
  description: "Understand your money, plan decisions, and build reusable financial tools with AI.",
  applicationName: "Moneo",
  appleWebApp: { capable: true, title: "Moneo", statusBarStyle: "default" },
  icons: { icon: "/icon-192.png", apple: "/apple-touch-icon.png" },
  other: { "apple-mobile-web-app-capable": "yes" },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover",
  themeColor: [{ media: "(prefers-color-scheme: light)", color: "#f4f3ee" }, { media: "(prefers-color-scheme: dark)", color: "#0f1011" }],
};

type Theme = "light" | "dark" | "system";

const themeStaysAtFallbackWithoutWorkspace = () => undefined;

async function WorkspaceTheme({ fallback }: { fallback: Theme }) {
  let theme = fallback;
  try { theme = (await requireWorkspace()).settings.theme; } catch { themeStaysAtFallbackWithoutWorkspace(); }
  return <ThemePreference preference={theme} />;
}

async function CallRecordSync() {
  let workspaceId: string;
  try { workspaceId = (await requireWorkspace()).workspace.id; } catch { return null; }
  return <PendingCallRecords workspaceId={workspaceId} />;
}

async function loadShellData(): Promise<ShellData> {
  try {
    const { supabase, workspace } = await requireWorkspace();
    const [accounts, recurring, reviews, jobs] = await Promise.all([
      supabase.from("accounts").select("id, name").eq("workspace_id", workspace.id).is("archived_at", null).order("name").limit(200),
      supabase.from("recurring_series").select("id", { count: "exact", head: true }).eq("workspace_id", workspace.id).eq("status", "pending"),
      supabase.from("organization_reviews").select("id", { count: "exact", head: true }).eq("workspace_id", workspace.id).eq("status", "pending"),
      supabase.from("background_jobs").select("id", { count: "exact", head: true }).eq("workspace_id", workspace.id).in("status", ["queued", "running"]),
    ]);
    return {
      accounts: accounts.data ?? [],
      counts: { "/money/recurring": recurring.count ?? 0, "/money/organization": reviews.count ?? 0, "/ai/activity": jobs.count ?? 0 },
    };
  } catch { return null; }
}

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const cookieTheme = (await cookies()).get("moneo-theme")?.value;
  const theme: Theme = cookieTheme === "light" || cookieTheme === "dark" ? cookieTheme : "system";
  return (
    <html lang="en" data-theme={theme} className={`${sans.variable} ${mono.variable} ${display.variable}`} suppressHydrationWarning>
      <body className="min-h-screen bg-background font-sans text-foreground antialiased">
        {hasSupabase() ? <Suspense fallback={<ThemePreference preference={theme} />}><WorkspaceTheme fallback={theme} /></Suspense> : <ThemePreference preference={theme} />}
        {hasSupabase() && <SyncOnOpen />}
        {hasSupabase() && <Suspense fallback={null}><CallRecordSync /></Suspense>}
        <ServiceWorker />
        <AppShell shell={hasSupabase() ? loadShellData() : Promise.resolve(null)}>{children}</AppShell>
      </body>
    </html>
  );
}
export { default } from "@/app/loading";
